import * as THREE from 'three';

export class BossAlien {
    constructor(scene, config, bus) {
        this.scene = scene;
        this.config = config;
        this.bus = bus;
        this.alive = false;
        this.hp = 0;
        this.maxHp = config.bossMaxHp;
        this.fireTimer = 0;
        this.fireInterval = 0.4;
        this.moveTimer = 0;
        this.moveDir = 1;
        this.mesh = null;
        this.group = null;
        this.baseY = 2.8;
        this.x = 0;
        this.y = this.baseY;
        this._createMesh();
    }

    _createMesh() {
        this.group = new THREE.Group();
        const geo = new THREE.BoxGeometry(1.2, 0.8, 0.6);
        const mat = new THREE.MeshStandardMaterial({
            color: 0x220022,
            emissive: 0xff0066,
            emissiveIntensity: 1.0,
            metalness: 0.5,
            roughness: 0.3
        });
        this.mesh = new THREE.Mesh(geo, mat);
        this.group.add(this.mesh);

        const eyeGeo = new THREE.SphereGeometry(0.12, 8, 8);
        const eyeMat = new THREE.MeshStandardMaterial({
            color: 0xffffff,
            emissive: 0xffffff,
            emissiveIntensity: 2.0
        });
        const leftEye = new THREE.Mesh(eyeGeo, eyeMat);
        leftEye.position.set(-0.3, 0.1, 0.3);
        this.group.add(leftEye);
        const rightEye = new THREE.Mesh(eyeGeo, eyeMat);
        rightEye.position.set(0.3, 0.1, 0.3);
        this.group.add(rightEye);

        this.group.visible = false;
        this.scene.add(this.group);
    }

    spawn() {
        this.alive = true;
        this.hp = this.maxHp;
        this.x = 0;
        this.y = this.baseY;
        this.fireTimer = 0;
        this.moveTimer = 0;
        this.moveDir = 1;
        this.group.visible = true;
        this.group.position.set(this.x, this.y, 0);
        this.mesh.material.emissiveIntensity = 1.0;
    }

    update(dt) {
        if (!this.alive) return;
        this.moveTimer += dt;
        if (this.moveTimer > 0.5) {
            this.moveTimer = 0;
            this.x += this.moveDir * 2.0;
            if (this.x > 4.5 || this.x < -4.5) {
                this.moveDir *= -1;
            }
            this.group.position.x = this.x;
        }
        this.y = this.baseY + Math.sin(performance.now() * 0.002) * 0.2;
        this.group.position.y = this.y;
        this.fireTimer += dt;
        if (this.fireTimer >= this.fireInterval) {
            this.fireTimer = 0;
            this._fire();
        }
        const flash = (this.hp / this.maxHp) < 0.3 ? 0.5 + Math.sin(performance.now() * 0.01) * 0.5 : 0;
        this.mesh.material.emissiveIntensity = 1.0 + flash;
    }

    _fire() {
        this.bus.emit('boss_fire', { x: this.x, y: this.y });
    }

    takeDamage() {
        if (!this.alive) return;
        this.hp--;
        this.bus.emit('boss_hit', { x: this.x, y: this.y });
        if (this.hp <= 0) {
            this.alive = false;
            this.group.visible = false;
            this.bus.emit('boss_death', { x: this.x, y: this.y });
        }
    }

    get position() {
        return { x: this.x, y: this.y };
    }

    getHitbox() {
        if (!this.alive) return null;
        return {
            minX: this.x - 0.6,
            maxX: this.x + 0.6,
            minY: this.y - 0.4,
            maxY: this.y + 0.4
        };
    }

    dispose() {
        this.scene.remove(this.group);
        this.group.traverse(child => {
            if (child.geometry) child.geometry.dispose();
            if (child.material) {
                if (Array.isArray(child.material)) {
                    child.material.forEach(m => m.dispose());
                } else {
                    child.material.dispose();
                }
            }
        });
    }
}

import CONFIG from './config.js';
import PlayerShip from './entities/PlayerShip.js';
import AlienGrid from './entities/AlienGrid.js';
import Shields from './entities/Shields.js';
import Bullets from './entities/Bullets.js';
import MysteryShip from './entities/MysteryShip.js';
import PowerUps from './entities/PowerUps.js';
import BossAlien from './entities/BossAlien.js';

export default class SpaceInvadersGame {
  constructor(sceneManager, input, bus, config, vfxManager, audioManager, ui) {
    this.scene = sceneManager.scene;
    this.camera = sceneManager.camera;
    this.input = input;
    this.bus = bus;
    this.config = config;
    this.vfx = vfxManager;
    this.audio = audioManager;
    this.ui = ui;

    this.state = 'MENU'; // MENU, PLAYING, PAUSED, WAVE_TRANSITION, GAME_OVER
    this.score = 0;
    this.combo = 0;
    this.comboTimer = 0;
    this.wave = 1;
    this.waveTransitionTimer = 0;

    this.player = null;
    this.alienGrid = null;
    this.shields = null;
    this.bullets = null;
    this.mysteryShip = null;
    this.powerUps = null;
    this.bossAlien = null;
    this.collisionManager = null;

    this.starfield = null;
    this.nebula = null;
    this.playerLight = null;

    this.elapsed = 0;
  }

  async init() {
    this._createEnvironment();
    this._createEntities();
    this._setupInput();
    this.ui.setState('MENU');
  }

  _createEnvironment() {
    // Nebula background
    const nebulaGeo = new THREE.PlaneGeometry(40, 30);
    const nebulaMat = new THREE.MeshStandardMaterial({
      color: 0x1a0033,
      emissive: 0x110022,
      emissiveIntensity: 0.3,
      side: THREE.DoubleSide,
    });
    this.nebula = new THREE.Mesh(nebulaGeo, nebulaMat);
    this.nebula.position.z = -15;
    this.scene.add(this.nebula);

    // Starfield
    this.starfield = this._createStarfield();
    this.scene.add(this.starfield);

    // Player-following point light
    this.playerLight = new THREE.PointLight(0x00ffff, 2, 8);
    this.scene.add(this.playerLight);
  }

  _createStarfield() {
    const group = new THREE.Group();
    const counts = [800, 600, 400];
    const sizes = [0.02, 0.04, 0.06];
    const speeds = [0.02, 0.04, 0.06];

    for (let layer = 0; layer < 3; layer++) {
      const count = counts[layer];
      const positions = new Float32Array(count * 3);
      const colors = new Float32Array(count * 3);

      for (let i = 0; i < count; i++) {
        positions[i * 3] = (Math.random() - 0.5) * 30;
        positions[i * 3 + 1] = (Math.random() - 0.5) * 20;
        positions[i * 3 + 2] = -5 - Math.random() * 10;

        const brightness = 0.3 + Math.random() * 0.7;
        colors[i * 3] = brightness;
        colors[i * 3 + 1] = brightness;
        colors[i * 3 + 2] = brightness + Math.random() * 0.2;
      }

      const geo = new THREE.BufferGeometry();
      geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
      geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));

      const mat = new THREE.PointsMaterial({
        size: sizes[layer],
        vertexColors: true,
        transparent: true,
        opacity: 0.8,
        sizeAttenuation: true,
      });

      const points = new THREE.Points(geo, mat);
      points.userData.driftSpeed = speeds[layer];
      group.add(points);
    }

    return group;
  }

  _createEntities() {
    this.player = new PlayerShip(this.scene, this.input, this.bus, this.config);
    this.alienGrid = new AlienGrid(this.scene, this.config, this.bus);
    this.shields = new Shields(this.scene, this.config);
    this.bullets = new Bullets(this.scene, this.config, this.bus);
    this.mysteryShip = new MysteryShip(this.scene, this.config, this.bus);
    this.powerUps = new PowerUps(this.scene, this.config, this.bus);
    this.collisionManager = new CollisionManager(this.bus, this.config);
  }

  _setupInput() {
    this.bus.on('input:fire', () => {
      if (this.state === 'MENU') {
        this._startGame();
      } else if (this.state === 'GAME_OVER') {
        this._resetToMenu();
      }
    });

    this.bus.on('input:special', () => {
      if (this.state === 'PLAYING') {
        this.state = 'PAUSED';
        this.ui.setState('PAUSED');
      } else if (this.state === 'PAUSED') {
        this.state = 'PLAYING';
        this.ui.setState('PLAYING');
      }
    });
  }

  _startGame() {
    this.state = 'PLAYING';
    this.score = 0;
    this.combo = 0;
    this.comboTimer = 0;
    this.wave = 1;
    this.player.reset();
    this.shields.reset();
    this.alienGrid.spawnWave(this.wave);
    this.mysteryShip.reset();
    this.powerUps.clear();
    this.bullets.clear();
    this.ui.setState('PLAYING');
    this.ui.updateScore(0, 0, 1);
    this.ui.updateHealth(this.player.hp, this.player.maxHp);
    this.audio.playWaveTransition();
  }

  _resetToMenu() {
    this.state = 'MENU';
    this.alienGrid.reset();
    this.player.reset();
    this.shields.reset();
    this.bullets.clear();
    this.mysteryShip.destroy();
    this.powerUps.clear();
    if (this.bossAlien) {
      this.bossAlien = null;
    }
    this.ui.hide();
    this.ui.setState('MENU');
  }

  _nextWave() {
    this.wave++;
    this.state = 'WAVE_TRANSITION';
    this.waveTransitionTimer = 2.0;
    this.player.reset();
    this.shields.reset();
    this.bullets.clear();
    this.powerUps.clear();
    this.alienGrid.reset();
    if (this.bossAlien) {
      this.bossAlien = null;
    }
    this.ui.setState('WAVE_TRANSITION');
    this.ui.updateScore(this.score, this.combo, this.wave);
    this.audio.playWaveTransition();
    this.vfx.cameraShake.addTrauma(0.3);
  }

  _gameOver() {
    this.state = 'GAME_OVER';
    this.ui.showGameOver(this.score);
    this.audio.playGameOver();
    this.vfx.cameraShake.addTrauma(0.8);
    this.vfx.hitStop.trigger(0.3);
  }

  _addScore(points, position) {
    this.combo++;
    this.comboTimer = 5.0;
    const multiplier = Math.min(3.0, 1.0 + (this.combo - 1) * 0.1);
    const totalPoints = Math.round(points * multiplier);
    this.score += totalPoints;
    this.ui.updateScore(this.score, this.combo, this.wave);
    this.vfx.scoreText.spawn(position, `+${totalPoints}`, 0xffffff);
  }

  update(dt) {
    if (this.state === 'MENU' || this.state === 'GAME_OVER') {
      this._updateStarfield(dt);
      return;
    }

    if (this.state === 'PAUSED') {
      return;
    }

    if (this.state === 'WAVE_TRANSITION') {
      this.waveTransitionTimer -= dt;
      this._updateStarfield(dt);
      if (this.waveTransitionTimer <= 0) {
        this.state = 'PLAYING';
        this.ui.setState('PLAYING');
        if (this.wave % 5 === 0) {
          this._spawnBoss();
        } else {
          this.alienGrid.spawnWave(this.wave);
        }
        this.mysteryShip.reset();
      }
      return;
    }

    // PLAYING state
    this.elapsed += dt;

    // Combo timeout
    if (this.comboTimer > 0) {
      this.comboTimer -= dt;
      if (this.comboTimer <= 0) {
        this.combo = 0;
        this.ui.updateScore(this.score, 0, this.wave);
      }
    }

    // Update entities
    this.player.update(dt);
    this.alienGrid.update(dt, this.elapsed);
    this.bullets.update(dt);
    this.mysteryShip.update(dt);
    this.powerUps.update(dt);

    // Boss
    if (this.bossAlien && this.bossAlien.alive) {
      this.bossAlien.update(dt, this.elapsed);
    }

    // Collision detection
    this._checkCollisions();

    // Check wave clear
    if (this.alienGrid.aliveCount === 0 && (!this.bossAlien || !this.bossAlien.alive)) {
      this._nextWave();
    }

    // Check alien invasion
    const aliens = this.alienGrid.aliens;
    for (const alien of aliens) {
      if (!alien.isDead() && alien.position.y < -2.5) {
        this._gameOver();
        return;
      }
    }

    // Update player light position
    if (this.playerLight) {
      this.playerLight.position.copy(this.player.position);
      this.playerLight.position.y += 0.5;
    }

    // Update starfield
    this._updateStarfield(dt);
  }

  _checkCollisions() {
    const playerBullets = this.bullets.playerBullets;
    const alienBullets = this.bullets.alienBullets;
    const aliens = this.alienGrid.aliens;
    const shieldCells = this.shields.getAliveCells();

    // Player bullets vs aliens
    for (const bullet of playerBullets) {
      if (!bullet.alive) continue;
      for (const alien of aliens) {
        if (alien.isDead()) continue;
        if (this._aabbTest(bullet, alien)) {
          bullet.alive = false;
          alien.takeDamage();
          this.bus.emit('alien:hit', { position: alien.position.clone(), type: alien.type });
          if (alien.isDead()) {
            this._addScore(this.config.alienTypes[alien.type].points, alien.position);
            this.bus.emit('alien:death', { position: alien.position.clone(), type: alien.type });
            // Power-up drop
            if (Math.random() < 0.05) {
              this.powerUps.spawn(alien.position);
            }
          }
          break;
        }
      }
    }

    // Player bullets vs mystery ship
    if (this.mysteryShip.active) {
      for (const bullet of playerBullets) {
        if (!bullet.alive) continue;
        if (this._aabbTest(bullet, this.mysteryShip)) {
          bullet.alive = false;
          this.mysteryShip.destroy();
          this.bus.emit('mystery:death', { position: this.mysteryShip.position.clone() });
          const points = this.mysteryShip.points || 300;
          this._addScore(points, this.mysteryShip.position);
          break;
        }
      }
    }

    // Player bullets vs boss
    if (this.bossAlien && this.bossAlien.alive) {
      for (const bullet of playerBullets) {
        if (!bullet.alive) continue;
        if (this._aabbTest(bullet, this.bossAlien)) {
          bullet.alive = false;
          this.bossAlien.takeDamage();
          this.bus.emit('boss:hit', { position: this.bossAlien.position.clone() });
          if (!this.bossAlien.alive) {
            this._addScore(1000, this.bossAlien.position);
            this.bus.emit('boss:death', { position: this.bossAlien.position.clone() });
          }
          break;
        }
      }
    }

    // Player bullets vs shields
    for (const bullet of playerBullets) {
      if (!bullet.alive) continue;
      if (this.shields.checkCollision(bullet.position)) {
        bullet.alive = false;
        this.shields.destroyAt(bullet.position, 0.3);
        this.bus.emit('shield:hit', { position: bullet.position.clone() });
      }
    }

    // Alien bullets vs player
    for (const bullet of alienBullets) {
      if (!bullet.alive) continue;
      if (this._aabbTest(bullet, this.player) && !this.player.invulnerable) {
        bullet.alive = false;
        this.player.takeDamage();
        this.bus.emit('player:hit', { position: this.player.position.clone() });
        this.ui.updateHealth(this.player.hp, this.player.maxHp);
        if (this.player.hp <= 0) {
          this._gameOver();
          return;
        }
        break;
      }
    }

    // Alien bullets vs shields
    for (const bullet of alienBullets) {
      if (!bullet.alive) continue;
      if (this.shields.checkCollision(bullet.position)) {
        bullet.alive = false;
        this.shields.destroyAt(bullet.position, 0.3);
        this.bus.emit('shield:hit', { position: bullet.position.clone() });
      }
    }

    // Aliens vs shields (aliens destroy shields on contact)
    for (const alien of aliens) {
      if (alien.isDead()) continue;
      if (this.shields.checkCollision(alien.position)) {
        this.shields.destroyAt(alien.position, 0.5);
      }
    }

    // Player vs power-ups
    this.powerUps.collect(this.player.position);

    // Player bullets vs alien bullets (they destroy each other)
    for (const pBullet of playerBullets) {
      if (!pBullet.alive) continue;
      for (const aBullet of alienBullets) {
        if (!aBullet.alive) continue;
        if (this._aabbTest(pBullet, aBullet)) {
          pBullet.alive = false;
          aBullet.alive = false;
          this.bus.emit('bullet:collision', {
            position: pBullet.position.clone()
          });
          break;
        }
      }
    }
  }

  _aabbTest(a, b) {
    const aHalf = a.halfSize || 0.2;
    const bHalf = b.halfSize || 0.2;
    const aPos = a.position;
    const bPos = b.position;

    return (
      Math.abs(aPos.x - bPos.x) < (aHalf + bHalf) &&
      Math.abs(aPos.y - bPos.y) < (aHalf + bHalf)
    );
  }

  _spawnBoss() {
    this.bossAlien = new BossAlien(this.scene, this.config, this.bus);
  }

  _updateStarfield(dt) {
    if (!this.starfield) return;
    for (const layer of this.starfield.children) {
      const positions = layer.geometry.attributes.position.array;
      const speed = layer.userData.driftSpeed || 0.02;
      for (let i = 1; i < positions.length; i += 3) {
        positions[i] -= speed * dt;
        if (positions[i] < -10) {
          positions[i] = 10;
        }
      }
      layer.geometry.attributes.position.needsUpdate = true;
    }
  }

  dispose() {
    this.bus.off('*');
    if (this.player) this.player.dispose();
    if (this.alienGrid) this.alienGrid.dispose();
    if (this.shields) this.shields.dispose();
    if (this.bullets) this.bullets.dispose();
    if (this.mysteryShip) this.mysteryShip.dispose();
    if (this.powerUps) this.powerUps.dispose();
    if (this.bossAlien) this.bossAlien.dispose();
    if (this.starfield) {
      for (const child of this.starfield.children) {
        child.geometry.dispose();
        child.material.dispose();
      }
      this.starfield.dispose();
    }
    if (this.nebula) {
      this.nebula.geometry.dispose();
      this.nebula.material.dispose();
    }
    if (this.playerLight) {
      this.playerLight.dispose();
    }
  }
}

