import SpaceInvadersGame from './SpaceInvadersGame.js';
import '../../styles/glassmorphism.css';

let gameLoop = null;
let sceneManager = null;
let postProcess = null;
let input = null;
let game = null;

async function init() {
    // Wait for user interaction to unlock audio
    await unlockAudio();

    // Create scene manager
    sceneManager = new SceneManager();

    // Create post-processing
    postProcess = new PostProcessStack(
        sceneManager.renderer,
        window.innerWidth,
        window.innerHeight
    );

    // Create input system
    input = new DualInput();
    input.connectKeyboard();

    // Create game
    game = new SpaceInvadersGame(sceneManager, input);

    // Handle resize
    window.addEventListener('resize', onResize);

    // Start game loop
    gameLoop = new GameLoop(game.update.bind(game), game.render.bind(game));
    gameLoop.start();
}

function unlockAudio() {
    return new Promise((resolve) => {
        // Check if audio is already unlocked
        try {
            const ctx = new (window.AudioContext || window.webkitAudioContext)();
            if (ctx.state === 'running') {
                ctx.close();
                resolve();
                return;
            }
            ctx.close();
        } catch (e) {
            // Ignore
        }

        // Wait for user interaction
        const handler = () => {
            document.removeEventListener('click', handler);
            document.removeEventListener('keydown', handler);
            resolve();
        };
        document.addEventListener('click', handler);
        document.addEventListener('keydown', handler);
    });
}

function onResize() {
    if (!sceneManager) return;
    sceneManager.onResize(window.innerWidth, window.innerHeight);
    if (postProcess) {
        postProcess.composer.setSize(window.innerWidth, window.innerHeight);
    }
}

// Start initialization
init().catch(console.error);

