import * as THREE from 'three'
import { ObjectPool } from '../../../shared/pool/ObjectPool.js'

export class Bullets {
  constructor(scene, config, bus) {
    this.scene = scene
    this.config = config
    this.bus = bus

    // Player bullet pool
    this.playerPool = new ObjectPool(() => this._createBullet(config.playerBulletColor, config.playerBulletEmissive), config.maxPlayerBullets)
    // Alien bullet pool
    this.alienPool = new ObjectPool(() => this._createBullet(config.alienBulletColor, config.alienBulletEmissive), config.maxAlienBullets)

    this.playerBullets = []
    this.alienBullets = []
  }

  _createBullet(color, emissive) {
    const geo = new THREE.BoxGeometry(0.06, 0.2, 0.06)
    const mat = new THREE.MeshStandardMaterial({
      color,
      emissive,
      emissiveIntensity: 1.5,
      metalness: 0.5,
      roughness: 0.3
    })
    const mesh = new THREE.Mesh(geo, mat)
    mesh.visible = false
    mesh.userData = {
      alive: false,
      velocity: new THREE.Vector3(),
      hitbox: { halfWidth: 0.06, halfHeight: 0.12 }
    }
    this.scene.add(mesh)
    return mesh
  }

  spawnPlayerBullet(position) {
    const bullet = this.playerPool.acquire()
    if (!bullet) return null
    bullet.position.copy(position)
    bullet.position.y += 0.3
    bullet.visible = true
    bullet.userData.alive = true
    bullet.userData.velocity.set(0, this.config.playerBulletSpeed, 0)
    this.playerBullets.push(bullet)
    return bullet
  }

  spawnAlienBullet(position) {
    const bullet = this.alienPool.acquire()
    if (!bullet) return null
    bullet.position.copy(position)
    bullet.position.y -= 0.2
    bullet.visible = true
    bullet.userData.alive = true
    bullet.userData.velocity.set(0, -this.config.alienBulletSpeed, 0)
    this.alienBullets.push(bullet)
    return bullet
  }

  update(dt) {
    // Update player bullets
    for (let i = this.playerBullets.length - 1; i >= 0; i--) {
      const b = this.playerBullets[i]
      b.position.addScaledVector(b.userData.velocity, dt)
      // Off screen top
      if (b.position.y > 5) {
        this._recyclePlayer(b)
        this.playerBullets.splice(i, 1)
      }
    }
    // Update alien bullets
    for (let i = this.alienBullets.length - 1; i >= 0; i--) {
      const b = this.alienBullets[i]
      b.position.addScaledVector(b.userData.velocity, dt)
      // Off screen bottom
      if (b.position.y < -5) {
        this._recycleAlien(b)
        this.alienBullets.splice(i, 1)
      }
    }
  }

  _recyclePlayer(bullet) {
    bullet.visible = false
    bullet.userData.alive = false
    this.playerPool.release(bullet)
  }

  _recycleAlien(bullet) {
    bullet.visible = false
    bullet.userData.alive = false
    this.alienPool.release(bullet)
  }

  removePlayerBullet(bullet) {
    const idx = this.playerBullets.indexOf(bullet)
    if (idx !== -1) {
      this.playerBullets.splice(idx, 1)
      this._recyclePlayer(bullet)
    }
  }

  removeAlienBullet(bullet) {
    const idx = this.alienBullets.indexOf(bullet)
    if (idx !== -1) {
      this.alienBullets.splice(idx, 1)
      this._recycleAlien(bullet)
    }
  }

  clear() {
    while (this.playerBullets.length > 0) {
      this._recyclePlayer(this.playerBullets.pop())
    }
    while (this.alienBullets.length > 0) {
      this._recycleAlien(this.alienBullets.pop())
    }
  }

  dispose() {
    this.clear()
    // Dispose geometries and materials
    const disposeBullet = (pool) => {
      // Release all back and dispose
      // We need to access internal pool items - dispose via scene children scan
    }
    // Dispose player bullet geometries/materials
    this.playerPool._items.forEach(b => {
      b.geometry.dispose()
      b.material.dispose()
      this.scene.remove(b)
    })
    this.alienPool._items.forEach(b => {
      b.geometry.dispose()
      b.material.dispose()
      this.scene.remove(b)
    })
  }
}

