import { CameraShake } from '../../../shared/vfx/CameraShake.js'
import { HitStop } from '../../../shared/vfx/HitStop.js'
import { MotionTrails } from '../../../shared/vfx/MotionTrails.js'
import { ShockwaveRings } from '../../../shared/vfx/ShockwaveRings.js'
import { FloatingScoreText } from '../../../shared/vfx/FloatingScoreText.js'
import { ParticleManager } from '../../../shared/particle/ParticleManager.js'

export function setupVFX(scene, bus, config) {
  const cameraShake = new CameraShake()
  const hitStop = new HitStop()
  const trails = new MotionTrails(scene)
  const rings = new ShockwaveRings(scene, 10)
  const scoreText = new FloatingScoreText(scene)
  const particles = new ParticleManager(scene, 500)

  // --- Alien death ---
  bus.on('alienDeath', (data) => {
    const color = config.alienTypes[data.type]?.color || '#ff6600'
    particles.burst('explosion', data.position, color, 30)
    rings.spawn(data.position, color)
    cameraShake.addTrauma(0.15)
    hitStop.trigger(0.03)
  })

  // --- Player hit ---
  bus.on('playerHit', (data) => {
    particles.burst('spark', data.position, '#ff0044', 20)
    cameraShake.addTrauma(0.3)
    hitStop.trigger(0.06)
  })

  // --- UFO death ---
  bus.on('ufoDeath', (data) => {
    particles.burst('explosion', data.position, '#ffdd00', 60)
    rings.spawn(data.position, '#ffdd00')
    cameraShake.addTrauma(0.5)
    hitStop.trigger(0.12)
  })

  // --- UFO appear ---
  bus.on('ufoAppear', () => {
    cameraShake.addTrauma(0.1)
  })

  // --- Player fire ---
  bus.on('playerFire', (data) => {
    particles.burst('spark', data.position, '#00ffff', 5)
  })

  // --- Alien fire ---
  bus.on('alienFire', (data) => {
    particles.burst('spark', data.position, '#ff3300', 5)
  })

  // --- Shield erosion ---
  bus.on('shieldErosion', (data) => {
    particles.burst('spark', data.position, '#00ff00', 8)
    cameraShake.addTrauma(0.05)
  })

  // --- Boss hit ---
  bus.on('bossHit', (data) => {
    particles.burst('explosion', data.position, '#ff0066', 40)
    rings.spawn(data.position, '#ff0066')
    cameraShake.addTrauma(0.4)
    hitStop.trigger(0.08)
  })

  // --- Boss death ---
  bus.on('bossDeath', (data) => {
    particles.burst('explosion', data.position, '#ff0066', 80)
    rings.spawn(data.position, '#ff0066')
    cameraShake.addTrauma(0.8)
    hitStop.trigger(0.15)
  })

  // --- Power-up collect ---
  bus.on('powerUpCollect', (data) => {
    particles.burst('spark', data.position, '#ffff00', 25)
  })

  // --- Wave clear ---
  bus.on('waveClear', () => {
    cameraShake.addTrauma(0.3)
    hitStop.trigger(0.1)
  })

  // --- Game over ---
  bus.on('gameOver', () => {
    cameraShake.addTrauma(1.0)
    hitStop.trigger(0.3)
  })

  // --- Bullet trails (spawn events) ---
  bus.on('playerBulletSpawn', (data) => {
    // trails handled by MotionTrails on the bullet mesh
  })

  bus.on('alienBulletSpawn', (data) => {
    // trails handled by MotionTrails on the bullet mesh
  })

  bus.on('ufoSpawn', (data) => {
    // UFO trail handled separately
  })

  function update(dt) {
    cameraShake.update(dt)
    hitStop.update(dt)
    trails.update(dt)
    rings.update(dt)
    scoreText.update(dt)
    particles.update(dt)
  }

  function applyShake(camera) {
    cameraShake.apply(camera)
  }

  function dispose() {
    trails.dispose()
    rings.dispose()
    scoreText.dispose()
    particles.dispose()
  }

  return { cameraShake, hitStop, trails, rings, scoreText, particles, update, applyShake, dispose }
}

import * as THREE from 'three';

export class PlayerShip {
  constructor(scene, input, bus, config) {
    this.input = input;
    this.bus = bus;
    this.config = config;
    this.hp = config.player.maxHp;
    this.maxHp = config.player.maxHp;
    this.vx = 0;
    this.x = 0;
    this.y = config.player.y;
    this.fireTimer = 0;
    this.invulnTimer = 0;
    this.invulnerable = false;
    this.blinkTimer = 0;
    this.blinkVisible = true;
    this.combo = 0;
    this.comboTimer = 0;
    this.powerUp = null;
    this.powerUpTimer = 0;

    // Create ship mesh
    const geo = new THREE.BoxGeometry(config.player.width, config.player.height, config.player.depth);
    const mat = new THREE.MeshStandardMaterial({
      color: 0x003344,
      emissive: 0x00ffff,
      emissiveIntensity: 0.5,
      metalness: 0.7,
      roughness: 0.2,
    });
    this.mesh = new THREE.Mesh(geo, mat);
    this.mesh.position.set(0, this.y, 0);
    scene.add(this.mesh);

    // Engine glow
    const glowGeo = new THREE.SphereGeometry(0.15, 8, 8);
    const glowMat = new THREE.MeshStandardMaterial({
      color: 0x00ffff,
      emissive: 0x00ffff,
      emissiveIntensity: 2.0,
      transparent: true,
      opacity: 0.8,
    });
    this.engineGlow = new THREE.Mesh(glowGeo, glowMat);
    this.engineGlow.position.set(0, -0.2, 0);
    this.mesh.add(this.engineGlow);

    // Point light following player
    this.light = new THREE.PointLight(0x00ffff, 2, 8);
    this.light.position.set(0, 0, 1);
    this.mesh.add(this.light);
  }

  get position() {
    return this.mesh.position;
  }

  get halfSize() {
    const c = this.config.player;
    return Math.max(c.width, c.height) / 2;
  }

  get aabb() {
    const c = this.config.player;
    return {
      minX: this.x - c.width / 2,
      maxX: this.x + c.width / 2,
      minY: this.y - c.height / 2,
      maxY: this.y + c.height / 2,
    };
  }

  update(dt, time) {
    // Movement
    const input = this.input.axis;
    let moveX = 0;
    if (input.left < 0) moveX -= 1;
    if (input.right > 0) moveX += 1;

    this.vx += moveX * this.config.player.accel * dt;
    this.vx = THREE.MathUtils.clamp(this.vx, -this.config.player.maxSpeed, this.config.player.maxSpeed);
    this.vx *= (1 - this.config.player.friction * dt);
    this.x += this.vx * dt;
    this.x = THREE.MathUtils.clamp(this.x, -this.config.bounds.x, this.config.bounds.x);

    this.mesh.position.x = this.x;

    // Engine glow pulse
    const pulse = 0.8 + 0.2 * Math.sin(time * 5);
    this.engineGlow.scale.setScalar(pulse);

    // Firing
    this.fireTimer -= dt;
    const fireRate = this.powerUp === 'rapidFire' ? this.config.player.fireCooldown * 0.4 : this.config.player.fireCooldown;
    if (input.fire && this.fireTimer <= 0) {
      this.fireTimer = fireRate;
      this.bus.emit('playerFire', { position: { x: this.x, y: this.y + this.config.player.height / 2 + 0.1 } });
    }

    // Invulnerability
    if (this.invulnerable) {
      this.invulnTimer -= dt;
      this.blinkTimer -= dt;
      if (this.blinkTimer <= 0) {
        this.blinkTimer = 0.0625; // 8 Hz
        this.blinkVisible = !this.blinkVisible;
        this.mesh.visible = this.blinkVisible;
      }
      if (this.invulnTimer <= 0) {
        this.invulnerable = false;
        this.mesh.visible = true;
        this.mesh.material.emissive.setHex(0x00ffff);
      }
    }

    // Power-up timer
    if (this.powerUp) {
      this.powerUpTimer -= dt;
      if (this.powerUpTimer <= 0) {
        this.powerUp = null;
        this.bus.emit('powerUpExpired', {});
      }
    }

    // Combo timer
    if (this.combo > 0) {
      this.comboTimer -= dt;
      if (this.comboTimer <= 0) {
        this.combo = 0;
      }
    }
  }

  takeDamage() {
    if (this.invulnerable) return false;
    this.hp--;
    this.invulnerable = true;
    this.invulnTimer = this.config.player.invulnDuration;
    this.combo = 0;
    this.mesh.material.emissive.setHex(0xff0000);
    this.bus.emit('playerHit', { position: { x: this.x, y: this.y } });
    return this.hp <= 0;
  }

  heal(amount) {
    this.hp = Math.min(this.maxHp, this.hp + amount);
  }

  addCombo() {
    this.combo++;
    this.comboTimer = 5.0;
  }

  getMultiplier() {
    return Math.min(3.0, 1.0 + this.combo * 0.1);
  }

  activatePowerUp(type) {
    this.powerUp = type;
    this.powerUpTimer = 8.0;
    this.bus.emit('powerUpActivated', { type });
  }

  dispose() {
    this.mesh.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        if (Array.isArray(child.material)) child.material.forEach(m => m.dispose());
        else child.material.dispose();
      }
    });
    if (this.light) this.light.dispose();
    this.mesh.parent?.remove(this.mesh);
  }
}

import * as THREE from 'three'
import { ObjectPool } from '../../../shared/pool/ObjectPool.js'

export class Bullets {
  constructor(scene, config, bus) {
    this.scene = scene
    this.config = config
    this.bus = bus

    this.playerPool = new ObjectPool(() => this._createBullet(config.playerBulletColor, config.playerBulletEmissive), config.maxPlayerBullets)
    this.alienPool = new ObjectPool(() => this._createBullet(config.alienBulletColor, config.alienBulletEmissive), config.maxAlienBullets)

    this.playerBullets = []
    this.alienBullets = []
  }

  _createBullet(color, emissive) {
    const geo = new THREE.BoxGeometry(0.06, 0.2, 0.06)
    const mat = new THREE.MeshStandardMaterial({
      color,
      emissive,
      emissiveIntensity: 1.5,
      metalness: 0.5,
      roughness: 0.3
    })
    const mesh = new THREE.Mesh(geo, mat)
    mesh.visible = false
    this.scene.add(mesh)

    // Wrapper object with direct properties the game code expects
    const bullet = {
      mesh,
      alive: false,
      position: new THREE.Vector3(),
      halfSize: 0.12,
      _geo: geo,
      _mat: mat
    }
    return bullet
  }

  spawnPlayerBullet(position) {
    const bullet = this.playerPool.acquire()
    if (!bullet) return null
    bullet.position.copy(position)
    bullet.position.y += 0.3
    bullet.mesh.position.copy(bullet.position)
    bullet.mesh.visible = true
    bullet.alive = true
    this.playerBullets.push(bullet)
    this.bus.emit('playerFire', { x: bullet.position.x, y: bullet.position.y })
    return bullet
  }

  spawnAlienBullet(position) {
    const bullet = this.alienPool.acquire()
    if (!bullet) return null
    bullet.position.copy(position)
    bullet.position.y -= 0.2
    bullet.mesh.position.copy(bullet.position)
    bullet.mesh.visible = true
    bullet.alive = true
    this.alienBullets.push(bullet)
    this.bus.emit('alien_fire', { x: bullet.position.x, y: bullet.position.y })
    return bullet
  }

  update(dt) {
    for (let i = this.playerBullets.length - 1; i >= 0; i--) {
      const b = this.playerBullets[i]
      b.position.y += this.config.playerBulletSpeed * dt
      b.mesh.position.copy(b.position)
      if (b.position.y > 5) {
        this._recyclePlayer(b)
        this.playerBullets.splice(i, 1)
      }
    }
    for (let i = this.alienBullets.length - 1; i >= 0; i--) {
      const b = this.alienBullets[i]
      b.position.y -= this.config.alienBulletSpeed * dt
      b.mesh.position.copy(b.position)
      if (b.position.y < -5) {
        this._recycleAlien(b)
        this.alienBullets.splice(i, 1)
      }
    }
  }

  _recyclePlayer(bullet) {
    bullet.alive = false
    bullet.mesh.visible = false
    this.playerPool.release(bullet)
  }

  _recycleAlien(bullet) {
    bullet.alive = false
    bullet.mesh.visible = false
    this.alienPool.release(bullet)
  }

  clear() {
    while (this.playerBullets.length > 0) {
      this._recyclePlayer(this.playerBullets.pop())
    }
    while (this.alienBullets.length > 0) {
      this._recycleAlien(this.alienBullets.pop())
    }
  }

  dispose() {
    this.clear()
    this.playerPool._items.forEach(b => {
      if (b._geo) b._geo.dispose()
      if (b._mat) b._mat.dispose()
      if (b.mesh && b.mesh.parent) b.mesh.parent.remove(b.mesh)
    })
    this.alienPool._items.forEach(b => {
      if (b._geo) b._geo.dispose()
      if (b._mat) b._mat.dispose()
      if (b.mesh && b.mesh.parent) b.mesh.parent.remove(b.mesh)
    })
  }
}

